INSERT INTO `perf_indicators` (`id`, `en_name`, `cn_name`, `en_description`, `cn_description`, `group_id`, `operator_code`, `data_type`, `unit_id`, `updator`, `uptime`, `is_build_in`, `is_counter`, `arithmetic`, `statis_type`, `calculating_status`, `product_types`, `num_id`, `indicator_level`) VALUES ('C000060101', 'PDCP.UpPktDelayDl', '小区用户面下行平均时延', 'delay is from PDCP SDU received to PDCP SDU sent, and summarize the time of total PDCP packet delay, mean value = Total delay/PDCP total packet number, each QCI is cosponding to a measurement itemsuccessfully sent defined as UE get the last segment ACK, MAC ACK for UM, RLC ACK for AM(3GPP TS 32.425)', '时延统计为从收到PDCP SDU到PDCP SDU成功发送之间所经历的时长，累加统计周期内所有的PDCP数据包时延，用总时延与该周期内成功发送的PDCP数据包总数之比表示平均值，每个QCI类型对应一个子测量项。成功发送定义为收到UE对PDCP SDU的最后一个分片的ACK确认，具体为UM模式下为MAC层ACK;AM模式下为RLC层ACK。（3GPP TS 32.425）。', 'c89c8327a43a4f4f9a39a3149e14e64f', NULL, '整数', 'ms', 'admin', '2018-03-31 00:00:00', '1', '1', 'C000060101', 'avg', '', 'BAIBLQ/BM/RTS/RTD/CR-B4860/MLN/MLQ', 61714, 'device');
