INSERT INTO `perf_indicators` (`id`, `en_name`, `cn_name`, `en_description`, `cn_description`, `group_id`, `operator_code`, `data_type`, `unit_id`, `updator`, `uptime`, `is_build_in`, `is_counter`, `arithmetic`, `statis_type`, `calculating_status`, `product_types`, `num_id`, `indicator_level`) VALUES ('C000090001', 'MAC.NbrTbUl', '上行传输TB数', 'Number of UL TB including retransmission TB. QCI1 TB is treated as voice schudeling TB', '统计小区上行传输的TB(Transport Block)数，包括重传的TB。单独统计包含QCI1的上行传输TB数作为语音调度上行TB块总数。', 'e8d5e91c19ab4aabab6fac8cab21ec28', NULL, '整数', 'number', 'admin', '2018-03-31 00:00:00', '1', '1', 'C000090001', 'sum', '', 'QRTB/BAIBLQ/BLX/BM/DXDF/RTS/RTD/CR-B4860/MLN/MLQ/NBIOT/QAFB/QAFA/QATA', 61995, 'device');
