INSERT INTO `perf_indicators` (`id`, `en_name`, `cn_name`, `en_description`, `cn_description`, `group_id`, `operator_code`, `data_type`, `unit_id`, `updator`, `uptime`, `is_build_in`, `is_counter`, `arithmetic`, `statis_type`, `calculating_status`, `product_types`, `num_id`, `indicator_level`) VALUES ('C000100018', 'PHY.ULMeanNL.SubCarrier0', '小区子载波（0～47）上行平均干扰电平', NULL, '采样统计每子载波上行干扰测量值，计算采样周期内采样值的平均值（线性平均，参考36.214）。采样间隔不超过5秒，每个子载波单独统计，子载波带宽为3.75KHz。（如果子载波带宽为15KHz，则15KHz子载波的测量统计干扰值，需要加-6dBm后复制到4个3.75KHz子载波上，始终输出48个测量值）', '84df5915a23f4455b3c88b6600ef0a41', NULL, NULL, 'dBm', 'admin', '2020-08-24 00:00:00', '1', '1', 'C000100018', 'avg', '', 'NBIOT', 62103, 'device');
