INSERT INTO `perf_indicators` (`id`, `en_name`, `cn_name`, `en_description`, `cn_description`, `group_id`, `operator_code`, `data_type`, `unit_id`, `updator`, `uptime`, `is_build_in`, `is_counter`, `arithmetic`, `statis_type`, `calculating_status`, `product_types`, `num_id`, `indicator_level`) VALUES ('C000100066', 'PHY.NbrCqiSum', '小区收到CQI总数', NULL, '小区收到的UE上报的CQI总数,见3GPP TS 36.213。在载波聚合场景下，若SCell的CQI经PCell的PUCCH上报，则CQI应计入Scell而不是Pcell的统计。空间复用条件下,一次上报两个码字的CQI分别计数。', '84df5915a23f4455b3c88b6600ef0a41', NULL, '整数', 'number', 'admin', '2021-10-11 00:00:00', '1', '1', 'C000100066', 'sum', '', 'QRTB/BAIBLQ/BLX/BM/CR-B4860/MLN/MLQ/QAFB/QAFA/QATA', 62151, 'device');
